export const PHYSICS_DEMYSTIFIED_ITEMS: PhysicsDemystifiedItem[] = RAW_DATA.map((d) => {
  const [chap, num, page, text, [A, B, C, D], ans, expl, imgName] = d;
  const meta = CHAPTER_LOOKUP[chap] || { title: 'General Physics', topic: 'General Physics' };
  const hasImage = Boolean(imgName);
  const imageUrl = hasImage ? `/assets/physics_diagrams/${imgName}` : undefined;

  return {
    id: `phy_demystified_c${chap}_q${num}_p${page}`,
    originalChapter: chap,
    chapterTitle: meta.title,
    topic: meta.topic,
    bookQuestionNum: num,
    text,
    options: { A, B, C, D },
    answer: ans,
    explanation: expl,
    page,
    hasImage,
    imageUrl,
    imageCaption: hasImage ? `Figure: Chapter ${chap} (${meta.topic}) · Question ${num}` : undefined,
    imageAlt: hasImage ? `Diagram for Physics Demystified Chapter ${chap} Question ${num}` : undefined,
  };
});

export function getPhysicsDemystifiedVerifiedQuestions(): VerifiedQuestion[] {
  return PHYSICS_DEMYSTIFIED_ITEMS.map((item, idx) => {
    return {
      id: 880000 + idx + 1,
      year: 2024,
      questionNumber: idx + 1,
      subject: 'Physics',
      topic: item.topic,
      text: item.text,
      options: item.options,
      answer: item.answer,
      explanation: `${item.explanation} [Physics Demystified by Dr. Timothy · Chapter ${item.originalChapter}: ${item.chapterTitle}, p. ${item.page}]`,
      bookTitle: 'PHYSICS DEMYSTIFIED',
      author: 'Dr. Aifuwa Timothy',
      textbookRef: `Physics Demystified by Dr. Timothy (Ch. ${item.originalChapter}: ${item.chapterTitle})`,
      hasImage: item.hasImage,
      imageUrl: item.imageUrl,
      imageCaption: item.imageCaption,
      imageAlt: item.imageAlt,
    };
  });
}
